mapper.select:
SELECT 'username'
WHERE EXISTS (
    SELECT 1
    FROM sys_user
    WHERE username = #{user.username}

        AND user_id != #{user.userId}

)
UNION ALL
SELECT 'email'
WHERE EXISTS (
    SELECT 1
    FROM sys_user
    WHERE email = #{user.email}

        AND user_id != #{user.userId}

)

SELECT * FROM sys_role WHERE role_id IN
#{id}
ORDER BY role_id FOR UPDATE

SELECT COUNT(*) FROM sys_user u JOIN sys_user_role ur ON ur.user_id = u.user_id AND ur.role_id = 1 JOIN sys_role r ON r.role_id = ur.role_id AND r.role_code = 'admin' AND r.status = 1 AND r.data_scope = 'ALL' WHERE u.status = 1 AND ( SELECT COUNT(*) FROM sys_role_permission rp JOIN sys_permission p ON p.permission_id = rp.permission_id AND p.status = 1 WHERE rp.role_id = 1 AND p.permission_code IN
#{code}
) = #{requiredCount}

mapper.update:
UPDATE sys_user
SET nickname = #{user.nickname},
    email = #{user.email},
    avatar = #{user.avatar},
    intro = #{user.intro}
WHERE user_id = #{user.userId}

UPDATE sys_user
SET password_hash = #{hash}
WHERE user_id = #{userId}

UPDATE sys_user
SET last_login_time = CURRENT_TIMESTAMP(3),
    last_login_ip = #{ip},
    last_login_location = #{location}
WHERE user_id = #{userId}
